// Узел trie: в конечном узле храним само слово (вместо флага isEnd)
class TrieNode {
  children = new Map<string, TrieNode>();
  word: string | null = null;
}

function findWords(board: string[][], words: string[]): string[] {
  // 1. Строим trie из всех слов словаря
  const root = new TrieNode();
  for (const w of words) {
    let node = root;
    for (const ch of w) {
      if (!node.children.has(ch)) node.children.set(ch, new TrieNode());
      node = node.children.get(ch)!;
    }
    node.word = w;
  }

  const m = board.length;
  const n = board[0].length;
  const result: string[] = [];

  // 2. DFS по доске, параллельно спускаясь по trie
  const dfs = (r: number, c: number, parent: TrieNode): void => {
    const ch = board[r][c];
    const node = parent.children.get(ch);
    // Нет такого продолжения ни у одного слова — обрываем ветку
    if (!node) return;

    if (node.word !== null) {
      result.push(node.word);
      // Обнуляем, чтобы не добавить то же слово повторно
      node.word = null;
    }

    // Помечаем клетку как занятую на время текущего пути
    board[r][c] = '#';
    if (r > 0) dfs(r - 1, c, node);
    if (r < m - 1) dfs(r + 1, c, node);
    if (c > 0) dfs(r, c - 1, node);
    if (c < n - 1) dfs(r, c + 1, node);
    // Возвращаем букву — откат (backtracking)
    board[r][c] = ch;

    // Оптимизация: опустевшую ветку удаляем, чтобы больше в неё не заходить
    if (node.children.size === 0 && node.word === null) {
      parent.children.delete(ch);
    }
  };

  // 3. Запускаем поиск из каждой клетки
  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      dfs(r, c, root);
    }
  }

  return result;
}

// Время: O(m · n · 4 · 3^(L-1)) в худшем случае, L — макс. длина слова (L <= 10)
//        + O(суммарная длина слов) на построение trie
// Память: O(суммарная длина слов) на trie + O(L) на стек рекурсии
